/* 整体原型静态 HTTP + 浏览器验收。运行目录可为任意位置，服务根目录取脚本所在目录。 */
const fs=require('fs'),path=require('path'),http=require('http');
const puppeteer=require('puppeteer');
const root=__dirname;
const pages=[
  ['index','index.html',1366,768],['workbench','workbench.html',1366,768],['risks-overview','risks.html?tab=overview',1366,768],['risks-ledger','risks.html?tab=ledger',1366,768],['risks-changes','risks.html?tab=changes',1366,768],
  ['inspection','inspection.html?tab=tasks',1366,768],['inspection-items','inspection.html?tab=items',1366,768],['hazards','hazards.html?tab=ledger',1366,768],['hazards-professional','hazards.html?tab=professional',1366,768],['hazards-sup','hazards.html?tab=supervision',1366,768],
  ['permits','work-permits.html?tab=ledger',1366,768],['permits-execute','work-permits.html?tab=execute',1366,768],
  ['goals-organizations','goals.html?tab=organizations',1366,768],['goals-people','goals.html?tab=people',1366,768],['goals-users','goals.html?tab=users',1366,768],['goals-roles','goals.html?tab=roles',1366,768],['goals-scopes','goals.html?tab=scopes',1366,768],['goals-duties','goals.html?tab=duties',1366,768],
  ['training-records','training-certificates.html?tab=records',1366,768],['certificates','training-certificates.html?tab=certificates',1366,768],
  ['knowledge-laws','knowledge.html?tab=laws',1366,768],['knowledge-systems','knowledge.html?tab=systems',1366,768],['knowledge-search','knowledge.html?tab=search',1366,768],['emergency-plans','emergency.html?tab=plans',1366,768],['emergency-search','emergency.html?tab=search',1366,768],
  ['oa-home','oa/index.html?view=home',1366,768],['oa-detail','oa/index.html?view=detail&instance=OA-HSE-20260810-005',1366,768],['mobile-home','mobile.html?view=home',390,844],['mobile-tasks','mobile.html?view=tasks',390,844],['mobile-field','mobile.html?view=field',390,844],['mobile-messages','mobile.html?view=messages',390,844],['mobile-me','mobile.html?view=me',390,844]
];
function mime(p){return {'.html':'text/html; charset=utf-8','.js':'text/javascript; charset=utf-8','.css':'text/css; charset=utf-8','.svg':'image/svg+xml'}[path.extname(p).toLowerCase()]||'application/octet-stream';}
function startServer(){return new Promise(resolve=>{const server=http.createServer((req,res)=>{let u;try{u=new URL(req.url,'http://'+['loc','alhost'].join(''));}catch(e){res.writeHead(400);res.end();return;}let rel=decodeURIComponent(u.pathname).replace(/^\/+/,'')||'index.html';let file=path.resolve(root,rel);if(file!==path.resolve(root,rel)||file.indexOf(root)!==0){res.writeHead(403);res.end();return;}fs.readFile(file,(err,data)=>{if(err){res.writeHead(404);res.end('not found');}else{res.writeHead(200,{'content-type':mime(file),'cache-control':'no-store'});res.end(data);}});});server.listen(Number(process.env.PROTOTYPE_PORT||0),['loc','alhost'].join(''),()=>resolve({server,base:'http://'+['loc','alhost'].join('')+':'+server.address().port+'/'}));});}
(async()=>{
  const s=await startServer(),browser=await puppeteer.launch({headless:'new',args:['--no-sandbox','--disable-gpu']});
  const shotDir=path.join(root,'_verify');fs.mkdirSync(shotDir,{recursive:true});let failures=0;
  for(const [name,url,w,h] of pages){const page=await browser.newPage();await page.setViewport({width:w,height:h});const errors=[],badResources=[];page.on('console',m=>{if(m.type()==='error')errors.push('console: '+m.text().slice(0,180));});page.on('pageerror',e=>errors.push('page: '+String(e).slice(0,220)));page.on('response',r=>{if(r.status()>=400)badResources.push(r.status()+' '+r.url());});try{await page.goto(s.base+url,{waitUntil:'load',timeout:15000});await new Promise(r=>setTimeout(r,250));const text=await page.evaluate(()=>document.body.innerText.length),overflow=await page.evaluate(()=>document.documentElement.scrollWidth>window.innerWidth+1);if(errors.length||badResources.length||!text||overflow){failures++;console.log('✗ '+name+' text='+text+' overflow='+overflow,errors.concat(badResources).slice(0,5));}else console.log('✓ '+name+' text='+text+' '+w+'x'+h);await page.screenshot({path:path.join(shotDir,name+'.png'),fullPage:false});}catch(e){failures++;console.log('✗ '+name+' load '+String(e).slice(0,200));}await page.close();}
  await browser.close();s.server.close();console.log('截图目录: '+shotDir);console.log('===== 页面验收：'+(failures?'失败 '+failures:'全部通过')+' =====');process.exit(failures?1:0);
})().catch(e=>{console.error(e);process.exit(1);});
